const rawRequest = $json.body ?? $json;
let request = rawRequest;
const errors = [];
if (typeof rawRequest === 'string') {
  try { request = JSON.parse(rawRequest); } catch { errors.push('Expected a JSON object.'); }
}
const textInput = (value) => value === null || value === undefined ? null : typeof value === 'string' ? value.trim() || null : undefined;
if (!request || typeof request !== 'object' || Array.isArray(request)) errors.push('Expected a JSON object.');
const fullName = textInput(request?.full_name);
const email = textInput(request?.email);
const phone = textInput(request?.phone);
const message = textInput(request?.message);
if (fullName === undefined || !fullName) errors.push('Full name is required.');
if (fullName && fullName.length > 160) errors.push('Full name is too long.');
if (email === undefined) errors.push('Email must be text when supplied.');
if (phone === undefined) errors.push('Phone must be text when supplied.');
if (!email && !phone) errors.push('An email address or phone number is required.');
if (email && (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254)) errors.push('Enter a valid email address.');
if (phone && (phone.length > 50 || !/^[0-9+().\-\s]{7,50}$/.test(phone) || (phone.match(/\d/g) || []).length < 7)) errors.push('Enter a valid phone number.');
if (message === undefined || !message) errors.push('Message is required.');
if (message && message.length > 5000) errors.push('Message is too long.');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (typeof request?.submission_id !== 'string' || !uuid.test(request.submission_id)) errors.push('Submission identifier is invalid.');
if (typeof request?.correlation_id !== 'string' || !uuid.test(request.correlation_id)) errors.push('Correlation identifier is invalid.');
if (typeof request?.received_at !== 'string' || Number.isNaN(Date.parse(request.received_at))) errors.push('Received timestamp is invalid.');
return [{ json: { input_valid: errors.length === 0, errors, request } }];

const request = $json.request;
const trim = (value) => typeof value === 'string' ? value.trim() || null : null;
return [{ json: {
  lead: {
    submission_id: request.submission_id,
    correlation_id: request.correlation_id,
    received_at: request.received_at,
    full_name: trim(request.full_name),
    email: trim(request.email)?.toLowerCase() ?? null,
    phone: trim(request.phone),
    original_message: request.message,
    normalized_message: trim(request.message)
  }
} }];

const lead = $('Normalize Contact Data').first().json.lead;
const result = $json;
const allowedServices = new Set(['furnace_service','air_conditioning_service','plumbing_service','electrical_service','general_home_service','unknown']);
const allowedUrgency = new Set(['low','medium','high','urgent']);
const safeText = (value, max) => typeof value === 'string' && value.trim() ? value.trim().slice(0, max) : null;
const error = result && typeof result.error === 'object' && result.error ? result.error : null;
const rawStatus = error?.httpCode ?? error?.statusCode ?? result?.statusCode;
const statusCode = Number.isInteger(rawStatus) && rawStatus >= 100 && rawStatus <= 599 ? rawStatus : null;
let enrichment = null;
let aiStatus = 'fallback_unavailable';
let diagnostic = 'NVIDIA NIM did not return a usable response.';
let providerMetadata = { provider: 'nvidia_nim', model_id: safeText($env.NVIDIA_NIM_MODEL, 160), outcome_class: 'provider_error', status_code: statusCode, error_code: safeText(error?.code ?? error?.name, 100), request_id: safeText(error?.requestId ?? error?.request_id, 160), execution_reference: safeText(String($execution?.id ?? ''), 160) };
try {
  if (error) throw new Error('Provider request failed');
  const content = result.choices?.[0]?.message?.content;
  const parsed = typeof content === 'string' ? JSON.parse(content) : null;
  const exactKeys = ['service_type', 'location', 'preferred_time', 'urgency', 'summary'];
  if (!parsed || typeof parsed !== 'object' || Object.keys(parsed).length !== exactKeys.length || Object.keys(parsed).some((key) => !exactKeys.includes(key))) throw new Error('Unexpected response shape');
  if (!allowedServices.has(parsed.service_type)) throw new Error('Unsupported service type');
  if (!allowedUrgency.has(parsed.urgency)) throw new Error('Unsupported urgency');
  for (const field of ['location', 'preferred_time']) {
    if (parsed[field] !== null && (typeof parsed[field] !== 'string' || !parsed[field].trim() || parsed[field].trim().length > 160)) throw new Error('Invalid optional text');
  }
  if (typeof parsed.summary !== 'string' || !parsed.summary.trim() || parsed.summary.trim().length > 600) throw new Error('Invalid summary');
  enrichment = { service_type: parsed.service_type, location: parsed.location?.trim() || null, preferred_time: parsed.preferred_time?.trim() || null, urgency: parsed.urgency, summary: parsed.summary.trim() };
  aiStatus = 'enriched';
  diagnostic = null;
  providerMetadata = { ...providerMetadata, outcome_class: 'enriched', status_code: statusCode ?? 200, error_code: null };
} catch (caught) {
  aiStatus = error ? 'fallback_unavailable' : 'fallback_invalid';
  diagnostic = aiStatus === 'fallback_invalid' ? 'NVIDIA NIM output failed application schema validation.' : diagnostic;
  providerMetadata = { ...providerMetadata, outcome_class: error ? 'provider_error' : 'invalid_output', error_code: providerMetadata.error_code ?? (error ? 'provider_error' : 'invalid_model_output') };
}
return [{ json: { crmPayload: { ...lead, enrichment, ai_status: aiStatus, needs_review: aiStatus !== 'enriched', enrichment_diagnostic: diagnostic, provider_metadata: providerMetadata } } }];

const expected = $('Validate AI Extraction').first().json.crmPayload;
const crm = $json;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const valid = !crm.error && typeof crm === 'object' && uuid.test(crm.crm_lead_id || '') && crm.submission_id === expected.submission_id && crm.correlation_id === expected.correlation_id && crm.pipeline_stage === 'new_lead' && crm.ai_status === expected.ai_status && ['created', 'replayed'].includes(crm.intake_state);
if (!valid) {
  return [{ json: { status_code: 502, response_body: { message: 'We could not confirm that your enquiry was saved. Please retry.' } } }];
}
return [{ json: { status_code: crm.intake_state === 'created' ? 201 : 200, response_body: { state: 'accepted', intake_state: crm.intake_state, submission_id: crm.submission_id, correlation_id: crm.correlation_id, crm_lead_id: crm.crm_lead_id, ai_status: crm.ai_status } } }];

return [{ json: {
  status_code: 422,
  response_body: { message: 'Please correct the highlighted enquiry details.', errors: $json.errors }
} }];
